        }
    }
    protected synchronized void closeLogFile() throws IOException {
        if (writer != null)
            writer.close();
        else
            p.println ("</logger>");
        if (f != null)
            f.close();
        f = null;
    }
    public void logRotate ()
        throws IOException
    {
        logRotate(false);
