216	    /** Parses a {@code <channel>} element, using the provided fallback realm when needed. */
217	    public ISOChannel newChannel (Element e, QFactory f, String fallbackRealm) throws ConfigurationException {
218	        String channelName  = QFactory.getAttributeValue (e, "class");
219	        String packagerName = QFactory.getAttributeValue (e, "packager");
220	
221	        ISOChannel channel = f.newInstance(channelName);
222	        if (packagerName != null) {
223	            ISOPackager packager = f.newInstance(packagerName);
224	            channel.setPackager (packager);
225	            f.setConfiguration (packager, e);
226	        }
227	        QFactory.invoke (channel, "setHeader", QFactory.getAttributeValue (e, "header"));
228	        f.setLogger       (channel, e, fallbackRealm);
229	        f.setConfiguration (channel, e);
230	
231	        if (channel instanceof FilteredChannel) {
232	            addFilters ((FilteredChannel) channel, e, f);
233	        }
234	
235	        if (channel instanceof ExceptionHandlerAware) {
236	            addExceptionHandlers((ExceptionHandlerAware) channel, e, f);
237	        }
238	
239	        if (channel instanceof ISOMsgMetrics.Source metricsChannel) {
240	            String type = "default";                                    // default alias, in case metrics not defined
241	            String clazz = null;
242	
243	            Element met = e.getChild("metrics");
244	            if (met != null) {
245	                if (QFactory.isEnabled(met)) {
246	                    clazz = QFactory.getAttributeValue(met, "class");
247	                    String typeAttr = QFactory.getAttributeValue(met, "type");
248	                    type =  (clazz != null)     ? "class"  :            // class attribute has precedence over type
249	                            (typeAttr != null)  ? typeAttr :
250	                            type;
251	                } else {
252	                    type = "none";                                      // <metrics enabled="false" /> equivalent to type="none"
253	                }
254	            }
255	
256	            ISOMsgMetrics m = switch (type) {
257	                case "none" -> null;
258	
259	                case "default" -> {
260	                    var mc = new ISOMsgCounter();
261	                    if (met != null)
262	                        f.setLogger(mc, met);
263	                    else
264	                        mc.setLogger(this.getLog().getLogger(), this.getRealm());
265	                    yield mc;
266	                }
267	
268	                case "counter" -> {
269	                    var mc = new ISOMsgCounter();
270	                    f.setLogger(mc, met);
271	                    f.setConfiguration(mc, met);
272	                    yield mc;
273	                }
274	
275	                case "class" -> {
276	                    ISOMsgMetrics mc = f.newInstance(clazz);
277	                    f.setLogger(mc, met);
278	                    f.setConfiguration(mc, met);
279	                    yield mc;
280	                }
281	
282	                default -> throw new ConfigurationException("Unknown metric type '"+type+"'");
283	            };
284	
285	            metricsChannel.setISOMsgMetrics(m);
286	        } // metrics config
287	
288	        if (getName () != null)
289	            channel.setName (getName ());
290	
291	        return channel;
292	    }
