294	    protected void addFilters (FilteredChannel channel, Element e, QFactory fact)
295	        throws ConfigurationException
296	    {
297	        for (Element f : e.getChildren("filter")) {
298	            ISOFilter filter = fact.newInstance(f);
299	            if (filter == null) continue;
300	            String direction = QFactory.getAttributeValue(f, "direction");
301	            if (direction == null)
302	                channel.addFilter(filter);
303	            else if ("incoming".equalsIgnoreCase(direction))
304	                channel.addIncomingFilter(filter);
305	            else if ("outgoing".equalsIgnoreCase(direction))
306	                channel.addOutgoingFilter(filter);
307	            else if ("both".equalsIgnoreCase(direction)) {
308	                channel.addIncomingFilter(filter);
309	                channel.addOutgoingFilter(filter);
310	            }
311	        }
312	    }
