197	    @Override
198	    public void run () {
199	        while (running()) {
200	            if (heavyLoaded()) {
201	                ISOUtil.sleep (100L);
202	                getLog().info ("HeavyLoaded - active sessions: " + getActiveSessions());
203	                continue;
204	            }
205	            Object obj = iisp.in (queue, MAX_WAIT);
206	            if (obj instanceof Serializable context) {
207	                if (getActiveSessions() <= maxSessions) {
208	                    if (context instanceof Context ctx)
209	                        ctx.log ("active=%d, maxSessions=%d".formatted(getActiveSessions(), maxSessions));
210	                    int session = activeSessions.incrementAndGet();
211	                    transactionCounter.increment();
212	                    executor.execute(() -> {
213	                        try {
214	                            runTransaction(context, session);
215	                        } finally {
216	                            activeSessions.decrementAndGet();
217	                        }
218	                    });
219	                }
220	                else {
221	                    iisp.push(queue, context);  // push it back
222	                    ISOUtil.sleep(100L);
223	                }
224	            }
225	        }
226	    }
