228	    private void runTransaction (Serializable context, int session) {
229	        long id = 0;
230	        List<TransactionParticipant> members;
231	        Iterator<TransactionParticipant> iter;
232	        boolean abort;
233	        LogEvent evt;
234	        Profiler prof;
235	        Thread thread = Thread.currentThread();
236	
237	        prof = null;
238	        evt = null;
239	        thread.setName (getName() + "-" + session + ":idle");
240	        int action = -1;
241	        id = head.getAndIncrement ();
242	        TMEvent tme = new TMEvent(getName(), id);
243	        Txn txn = new Txn(getName(), id);
244	
245	        tme.begin();
246	        try {
247	            setThreadLocal(id, context);
248	            if (hasStatusListeners)
249	                notifyStatusListeners (session, TransactionStatusEvent.State.READY, id, "", null);
250	
251	            Chronometer chronometer = new Chronometer(getStart(context));
252	
253	            abort = false;
254	            members = new ArrayList<> ();
255	            iter = getParticipants (DEFAULT_GROUP).iterator();
256	            evt = new LogEvent()
257	              .withSource(log)
258	              .withTraceId(getTraceId(id));
259	            evt.addMessage(txn);
260	            evt.addMessage(context);
261	            prof = new Profiler();
262	            snapshot (id, context, PREPARING);
263	            action = prepare (session, id, context, members, iter, abort, evt, prof, chronometer);
264	            switch (action) {
265	                case PREPARED:
266	                    if (members.size() > 0) {
267	                        setState(id, COMMITTING);
268	                        commit(session, id, context, members, false, evt, prof);
269	                    }
270	                    break;
271	                case ABORTED:
272	                    if (members.size() > 0) {
273	                        abort(session, id, context, members, false, evt, prof);
274	                    }
275	                    break;
276	                case RETRY:
277	                    psp.out (RETRY_QUEUE, context);
278	                    checkRetryTask();
279	                    break;
280	                case NO_JOIN:
281	                    break;
282	            }
283	            snapshot (id, null, DONE);
284	            if (id == tail.get()) {
285	                checkTail ();
286	            } else {
287	                purge (id, false);
288	            }
289	            tps.tick();
290	        } catch (Throwable t) {
291	            if (evt == null)
292	                getLog().fatal (t); // should never happen
293	            else
294	                evt.addMessage (t);
295	        } finally {
296	            removeThreadLocal();
297	            if (hasStatusListeners) {
298	                notifyStatusListeners (
299	                  session,
300	                  TransactionStatusEvent.State.DONE,
301	                  id, "", context);
302	            }
303	            if (evt != null && (action == PREPARED || action == ABORTED || (action == -1 && prof != null))) {
304	                switch (action) {
305	                    case PREPARED :
306	                        evt.setTag("commit");
307	                        break;
308	                    case ABORTED :
309	                        evt.setTag ("abort");
310	                        break;
311	                    case -1:
312	                        evt.setTag ("undefined");
313	                        break;
314	                }
315	                if (getInTransit() > Math.max(maxActiveTransactions, activeSessions.get()) * 100L) {
316	                    evt.addMessage("WARNING: IN-TRANSIT TOO HIGH");
317	                }
318	                evt.addMessage (
319	                  String.format (" %s, elapsed=%dms",
320	                    tmInfo(),
321	                    prof.getElapsedInMillis()
322	                  )
323	                );
324	                evt.addMessage (prof);
325	                try {
326	                    Logger.log(freeze(context, evt, prof));
327	                } catch (Throwable t) {
328	                    getLog().error(t);
329	                }
330	            }
331	            tme.commit();
332	        }
333	    }
