 96	    public void setConfiguration (Configuration cfg)
 97	        throws ConfigurationException
 98	    {
 99	        if (maxCopies == 0) {
100	            maxCopies = cfg.getInt("copies", 0);
101	        }
102	
103	        if (sleepTime == 0) {
104	            sleepTime = cfg.getInt("window") * 1000;
105	        }
106	
107	        if (logName == null) {
108	            logName = cfg.get ("file");
109	        }
110	
111	        // This check allows derived classes to have a different default.
112	        if (maxSize == 0) {
113	            maxSize = cfg.getLong("maxsize");
114	            maxSize = maxSize <= 0 ? DEFAULT_MAXSIZE : maxSize;
115	        }
116	
117	        rotateOnStartup = cfg.getBoolean("rotate-on-startup", false);
118	
119	        if (fileNamePattern == null) {
120	            fileNamePattern = cfg.get("file-name-pattern", null);
121	        }
122	
123	        if (fileNamePattern != null && !fileNamePattern.isEmpty()) {
124	            logName = fileNameFromPattern(logName, fileNamePattern);
125	        }
126	
127	        if (timer == null) {
128	            timer = () -> {
129	                Timer timer = DefaultTimer.getTimer();
130	                if (sleepTime != 0) timer.schedule(rotate = new Rotate(), sleepTime, sleepTime);
131	            };
132	        }
133	
134	        if (rotationAlgo == null) {
135	            rotationAlgo = () -> {
136	                for (int i = maxCopies; i > 0; ) {
137	                    File dest = new File(logName + "." + i);
138	                    File source = new File(logName + (--i > 0 ? "." + i : ""));
139	                    dest.delete();
140	                    source.renameTo(dest);
141	                }
142	            };
143	        }
144	    }
